)
func main(){
  var wg sync.WaitGroup
  names := []string{"Alice","Bob"}
  for _, n := range names {
    wg.Add(1)
    go func(name string){
      defer wg.Done()
      s, err := cg.GetGreeting(name)
      if err != nil { fmt.Println("err", err); return }
      fmt.Println(s)
    }(n)
  }
  wg.Wait()
}
